import ast, hashlib, importlib.util, json, pathlib
root=pathlib.Path('/workspace');p=json.load(open(root/'proposal.json'));r=json.load(open('/tmp/r001.json'))
assert len(p['variants'])==4
assert len(set(v['name'] for v in p['variants']))==4
assert len(set(v['file'] for v in p['variants']))==4
assert any(v['role']=='candidate' for v in p['variants'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
if importlib.util.find_spec('jsonschema'):
 import jsonschema
 jsonschema.validate(p['study'],r['study_schema']);print('JSON schema passed')
else:
 # Validate all constraints used by this schema without installations.
 def validate(value,schema):
  types={'object':dict,'array':list,'string':str,'boolean':bool}
  if 'type' in schema: assert isinstance(value,types[schema['type']]),(value,schema)
  if 'enum' in schema:assert value in schema['enum']
  if 'const' in schema:assert value==schema['const']
  if isinstance(value,dict):
   assert set(schema.get('required',[]))<=set(value)
   if schema.get('additionalProperties') is False:assert set(value)<=set(schema['properties'])
   for k,v in value.items():
    if k in schema.get('properties',{}):validate(v,schema['properties'][k])
  if isinstance(value,list):
   assert len(value)>=schema.get('minItems',0)
   for v in value:validate(v,schema['items'])
  if isinstance(value,str):assert len(value)>=schema.get('minLength',0)
 validate(p['study'],r['study_schema']);print('Study schema constraints passed (stdlib validator)')

def cls_methods(path):
 t=ast.parse(path.read_text());c=next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 return t,{n.name:n for n in c.body if isinstance(n,ast.FunctionDef)}
parent=root/'history_g1_r0047_match_history_mean_click_task.py'
pt,pm=cls_methods(parent)
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
first=None
for v in p['variants']:
 path=root/v['file'];source=path.read_text();compile(source,str(path),'exec');t,m=cls_methods(path)
 config=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert config==v['config']
 init=m['__init__'];defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in config.items():
  got=ast.literal_eval(defaults[k]);assert list(got) == val if isinstance(got,tuple) else got==val,(k,got,val)
 for node in ast.walk(t):
  if isinstance(node,ast.Import):assert all(a.name.split('.')[0] in allowed for a in node.names)
  if isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in allowed
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in ['open','exec','eval','compile','__import__','input']
  if isinstance(node,ast.Attribute):assert node.attr not in ['load','save','from_file','tofile','system','popen','environ']
 changed=[name for name in pm if ast.dump(pm[name],include_attributes=False)"'!=ast.dump(m[name],include_attributes=False)]
 assert set(changed)=={'"'__init__','_history_stratified_summary_values'},changed
 assert set(m)==set(pm)
 for n in t.body:
  if isinstance(n,ast.ClassDef):
   for q in n.body:
    assert not isinstance(q,(ast.Import,ast.ImportFrom))
 # All variant nonconstructor methods are identical.
 methods={name:ast.dump(node,include_attributes=False) for name,node in m.items() if name"'!='"'__init__'}
 if first is None:first=methods
 else:assert methods==first
 # Original-direction branch is structurally the exact parent helper, after removal of the added conditional.
 clean=ast.parse(ast.unparse(m['_history_stratified_summary_values'])).body[0]
 original=ast.parse(ast.unparse(pm['_history_stratified_summary_values'])).body[0]
 clean.body=clean.body[1:];original.body=original.body[1:]
 for node in ast.walk(clean):
  if isinstance(node,ast.With):
   node.body=[b for b in node.body if not (isinstance(b,ast.If) and 'summary_contrast_direction' in ast.unparse(b.test))]
 assert ast.dump(clean,include_attributes=False)==ast.dump(original,include_attributes=False)
 print(path.name,'syntax/config/import/ownership-source/parity-branch checks passed; changed methods',changed,'SHA256',hashlib.sha256(source.encode()).hexdigest())
print('No torch execution, training, source-readiness or host masking certificate claimed.')
